contract InvMutTest {
    C c;
    bytes4 constant ADDMSG_SIG = bytes4(keccak256("AddMessage(address,uint256,string)"));
    address lastSender;
    uint256 lastVal;
    uint256 lastDataLen;
    bytes lastData;

    constructor(C _c) { c = _c; }

    function run(uint256 d, uint256 am) public payable {
        require(d > 0 && am > 0 && am <= d);
        require(address(this).balance >= d);
        c.SetLogFile(address(this));
        c.Deposit{value: d}();
        uint256 balBefore = c.balances(address(this));
        bool reverted;
        try c.Collect(am) { reverted = false; }
        catch { reverted = true; }
        assert(
            !reverted &&
            balBefore >= am &&
            c.balances(address(this)) == balBefore - am &&
            lastSender == address(this) &&
            lastVal == am &&
            lastDataLen == 7 &&
            lastData.length == 7 &&
            lastData[0] == "C" &&
            lastData[1] == "o" &&
            lastData[2] == "l" &&
            lastData[3] == "l" &&
            lastData[4] == "e" &&
            lastData[5] == "c" &&
            lastData[6] == "t"
        );
    }

    fallback(bytes calldata input) external payable returns (bytes memory) {
        if (input.length >= 4 && bytes4(input[:4]) == ADDMSG_SIG && input.length >= 132) {
            lastSender = address(bytes20(input[4:24]));
            lastVal = uint256(bytes32(input[36:68]));
            uint256 off = uint256(bytes32(input[68:100]));
            uint256 len = uint256(bytes32(input[100 + off:132 + off]));
            lastDataLen = len;
            delete lastData;
            for (uint256 i = 0; i < len && i < 64 && 132 + off + i < input.length; i++) {
                lastData.push(input[132 + off + i]);
            }
        }
        return "";
    }

    receive() external payable {}
}

